INSERT INTO analytics_events ("id", "eventType", "auth0Id", "email", "payload", "occurredAt")
SELECT se.id::uuid, et."eventType"::analytics_events_eventtype_enum, ui."auth0Id", ui.email, se.payload, se."occurredAt"::timestamp
FROM seed_events se
JOIN event_types et ON et.code = se.event_code
LEFT JOIN user_idx ui ON ui.idx = se.user_i
ON CONFLICT ("id")
DO NOTHING;